namespace Umbraco.Bench.Umbraco.Models.Blocks;

// Carries the shared blockSettings element (spacing, background, anchor) and maps
// them to the Tailwind classes the component views apply, so the views stay markup-only.
public abstract class BlockModel
{
    public string Spacing { get; set; } = "medium";

    public string Background { get; set; } = "default";

    public string? Anchor { get; set; }

    public string SpacingClass => Spacing switch
    {
        "none" => "py-0",
        "small" => "py-8",
        "large" => "py-20",
        _ => "py-12",
    };

    public string BackgroundClass => Background switch
    {
        "subtle" => "bg-slate-100 text-slate-900",
        "accent" => "bg-indigo-600 text-white",
        _ => "bg-white text-slate-900",
    };
}

namespace Umbraco.Bench.Umbraco.Models.Blocks;

public sealed class HeroModel : BlockModel
{
    public string Eyebrow { get; set; } = "";

    public string Heading { get; set; } = "";

    public string Text { get; set; } = "";

    public string? ImageUrl { get; set; }

    public string ImageAlt { get; set; } = "";
}

namespace Umbraco.Bench.Umbraco.Models.Blocks;

public sealed class TextModel : BlockModel
{
    // Raw HTML from the rich text editor; the component view renders it with Html.Raw.
    public string Text { get; set; } = "";
}

namespace Umbraco.Bench.Umbraco.Models.Blocks;

public sealed class ImageModel : BlockModel
{
    public string? ImageUrl { get; set; }

    public string ImageAlt { get; set; } = "";

    public string? Caption { get; set; }
}

