@inherits UmbracoViewPage<BlogFrontPage>
@using Umbraco.Bench.Umbraco.Models
@{
    Layout = null;
    var posts = Model.Children<BlogPost>().OrderByDescending(post => post.PublishDate).ToList();
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@Model.PageTitle</title>
    <link rel="icon" href="~/favicon.ico" />
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</head>
<body class="bg-white text-slate-900 antialiased">
    @await Html.GetBlockGridHtmlAsync(Model, "body")

    <section class="py-16">
        <div class="mx-auto max-w-6xl px-6">
            <h2 class="mb-8 text-3xl font-bold tracking-tight">Latest posts</h2>
            <div class="grid gap-8 md:grid-cols-2">
                @foreach (var post in posts)
                {
                    <a href="@post.Url()" class="group rounded-2xl border border-slate-200 p-6 transition hover:border-indigo-400 hover:shadow-lg">
                        @if (post.HeroImage != null)
                        {
                            <img src="@post.HeroImage.GetCropUrl(width: 800, height: 450)" alt="@post.Title" class="mb-5 h-48 w-full rounded-xl object-cover" />
                        }
                        <p class="mb-2 text-sm font-semibold uppercase tracking-widest text-indigo-600">@post.PublishDate.ToString("MMMM d, yyyy")</p>
                        <h3 class="mb-2 text-2xl font-bold tracking-tight group-hover:text-indigo-600">@post.Title</h3>
                        <p class="leading-relaxed text-slate-600">@post.Summary</p>
                    </a>
                }
            </div>
        </div>
    </section>
</body>
</html>

